"""Build reviewable page specifications and SVG wireframes, not Power BI reports."""
import html
import json
from pathlib import Path
import textwrap

HERE=Path(__file__).resolve().parent
ROOT=HERE.parent
pages=[]
def page(title,question,qualifier):
    p=dict(number=len(pages)+1,title=title,question=question,qualifier=qualifier,canvas=[1280,800],visuals=[])
    pages.append(p); return p
def v(p,id,title,kind,source,axis,values,rect,filters='Current local Date selection',sort='Axis ascending',tooltip='Scope, units, selected dates, denominator, release 38',interaction='Date filters; chart clicks filter detail only',format='White card; dark text; teal; units in title'):
    p['visuals'].append(dict(id=id,title=title,type=kind,source=source,axis=axis,values=values,rect=rect,filters=filters,sort=sort,tooltip=tooltip,interaction=interaction,format=format))
p=page('Executive Market Monitor','How did price exposure and the extreme tail differ?','Historical release · Sep 2025–Aug 2026 · National includes Unknown')
v(p,'P1.1','Price / P95 / population SD · NZD/MWh','Card group','FactNational','—',['Weighted Wholesale Price','P95 Price','Price Volatility'],[28,128,600,108])
v(p,'P1.2','Demand GWh / peak MW / events / hours','Card group','FactNational; Events','—',['Total Demand GWh','Peak Demand MW','Pressure Events','Pressure Hours'],[648,128,604,108],tooltip='Events start on selected dates; hours are selected flagged intervals')
v(p,'P1.3','Monthly exposure and tail · NZD/MWh','Line chart','DimDate; FactNational','DimDate[Year-Month]',['Weighted Wholesale Price','P95 Price'],[28,254,760,252],tooltip='Weighted ratio of sums; P95 of half-hours; no average of monthly averages',format='Solid teal exposure; dotted orange P95; one unit/axis')
