v(p,'P1.5','Regional pressure visible beyond National','Column chart','DimDate; RegionalSignal','DimDate[Year-Month]',['Any-Zone Flagged Half-hours','Zone-only Half-hours'],[28,526,760,164],tooltip='Unique interval counts, not scoped event totals; known Zones only')
v(p,'P1.6','Coverage / threshold / retained assessment','Table','FactNational; Threshold; DQResults','—',['Priced Offtake Coverage','Offtake Zone Coverage','Full-period P99 threshold','DQ WARN'],[808,526,444,164],interaction='Date changes coverage; threshold and retained DQ fixed',format='Compact status table rather than extra headline cards; coverage %, P99 NZD/MWh, WARN label; no score')
