v(p,'P2.3','Price and own full-period threshold · NZD/MWh','Clustered bar chart','DimZone; FactZone; Threshold','DimZone[zone]',['Zone Weighted Wholesale Price','Zone Full-period P99 threshold'],[28,248,580,212],filters='Visual: five known Zones; Date selection',sort='Zone alphabetical',tooltip='Own stored P99; priced Offtake coverage; mean exposure is not tail incidence')
