v(p,'P2.7','Full-release regional event browser → investigate','Table','Events','event_id, zone, local_start, local_end',['Event Duration','Event Weighted Price','Peak Event Price'],[28,656,1224,106],filters='Events[scope]=Zone; separate Events zone/start_date filter pane; NOT global Date/DimZone',sort='local_start ascending, event_id tie-break',interaction='Right-click event_id → P4; keep all filters OFF',format='Full-release list label; do not label 361 or 429 unique market episodes')
