v(p,'P3.2','Absolute listed generation · GWh','Stacked column chart','DimDate; FactNational','DimDate[Year-Month]',['Renewable GWh','Fossil Thermal GWh','Storage GWh','Unclassified GWh'],[28,246,760,250],format='Renewable green; fossil orange; storage purple; unclassified grey; zero baseline')
v(p,'P3.3','Primary composition · Renewable + Fossil only','Line chart','DimDate; FactNational','DimDate[Year-Month]',['Renewable Primary Share','Fossil Thermal Share'],[808,246,444,250],format='0–100%; explicit denominator; Storage/Unclassified excluded')
v(p,'P3.4','National pressure vs non-pressure context','Table','FactNational','FactNational[is_price_pressure]',['Mean Demand MW','Renewable Primary Share','Fossil Thermal GWh','Storage GWh','Classification Coverage'],[28,516,760,170],tooltip='GWh is total exposure, not per-interval intensity; duration differs between groups',format='Show true/false as Pressure/Non-pressure; descriptive only; no causal arrows')
v(p,'P3.5','Fixed full-release matched demand context · MW','Card group','DemandBenchmark','—',['Release Pressure Mean MW','Release Matched Comparator MW','Release Matched Difference Pct'],[808,516,444,170],filters='Full release, disconnected',interaction='No date/pressure interaction',tooltip='Same local month/hour; 176 matched; minimum 51 controls; not causal matching')
v(p,'P3.6','Read both scale and mix','Text','Phase 5 F4/F5','—',[],[28,706,1224,56],filters='Fixed release',sort='—',interaction='None',format='Absolute renewable output is higher in pressure intervals; its primary share is lower. Classification limits remain visible.')
p=page('Price Pressure Investigation','What happened during this specific scoped event?','Event end exclusive · full-event metrics · UTC identity, NZ local display')
v(p,'P4.1','Choose one event · E1 E2 E3 E4 E5','Slicer / bookmark buttons','Events','Events[event_id]',[],[28,126,1224,60],filters='No synced date/hour/pressure filters',sort='Event ID ascending',interaction='Single selection filters Events → bridge/context; presets only event slicer',format='Event ID search ON; buttons E1–E5 and Reset event')
v(p,'P4.2','Full scoped event · hours / price / peak / demand','Card group','Events','—',['Event Duration','Event Weighted Price','Peak Event Price','Event Mean Demand MW','Event Regional Spread'],[28,202,1224,104],filters='Exactly one event; full duration',tooltip='Scope, Zone, local_start/end, start_utc/end_utc, full-release threshold',interaction='Event only; disable heatmap-to-card filtering')
v(p,'P4.3','Scoped interval price · NZD/MWh','Line chart','DimInterval; Events; facts','DimInterval[start_utc]',['Event Interval Price'],[28,326,710,182],filters='Event Interval Visible=1; no synced Date',sort='UTC ascending',tooltip='local_start, trading_period, utc_offset_minutes, fold; fixed event threshold',interaction='Event only; do not filter summary cards')
v(p,'P4.4','Zone participation · each Zone’s own P99','Matrix','DimInterval; DimZone; FactZone','Rows=start_utc; columns=zone',['Zone Pressure Flag'],[758,326,494,182],filters='Event Interval Visible=1; known Zones only',sort='UTC ascending / Zone alphabetical',tooltip='Local time + TP + offset + fold; 1=flag, 0=below own P99',format='Text 0/1 plus orange/white; no totals')
v(p,'P4.5','National context across the complete selected event','Card group','FactNational via EventInterval','—',['Event National Demand MW','Event National Weighted Price','Event National Renewable Share','Event National Classification Coverage','Event National Offtake Coverage','Event National Generation Coverage'],[28,528,1224,94],filters='Event membership, full event',tooltip='Even for E3, this panel is National context; not the selected Zone',interaction='Event only')
v(p,'P4.6','Measured event identity','Table','Events','event_id, scope, zone, local_start, local_end, start_utc, end_utc',[],[28,642,580,120],filters='One event',sort='—',interaction='Event only',format='UTC/local explicit; end exclusive; horizontal scroll if needed')
v(p,'P4.7','Electricity Authority context — separately sourced','Table','CaseContext','publisher, title, locator, url, supported_context, qualification, review_date',[],[628,642,624,120],filters='Events selection; non-case events have no curated context',sort='—',tooltip='Selected contrast cases, not incidence sample; exact cause can remain unresolved',interaction='External URL manually opened; no local-file link integration',format='Wrap text; larger focus-mode view for full qualification; never hide it')
