v(p,'P5.1','Retained DQ assessment · PASS / WARN / FAIL','Card group','DQResults','—',['DQ PASS','DQ WARN','DQ FAIL'],[28,128,580,98],filters='Fixed run 5; no Date/source filters',interaction='None; statuses keep original meaning',format='21 PASS, 8 WARN, 0 FAIL text plus restrained colours')
