(HERE/'page_specification.json').write_text(json.dumps(pages,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
doc=['# Five-page visual register','', 'These are construction specifications and wireframes, not screenshots of a working Power BI report. Rectangles are x/y/width/height on a 1280×800 canvas. Every measure name resolves to measure_catalog.json. See [build steps](powerbi_build_steps.md) and [interactions](powerbi_interactions.md).','']
wire=HERE/'wireframes'; wire.mkdir(exist_ok=True)
for p in pages:
    doc += [f'## {p["number"]}. {p["title"]}','',p['question'],'',p['qualifier'],'',f'![Page {p["number"]} wireframe](../powerbi/wireframes/page_{p["number"]}.svg)','', '| ID / visual | Binding | Filters / sorting | Tooltip / interaction | Formatting / position |','|---|---|---|---|---|']
    esc=lambda s:str(s).replace('|','/').replace('\n',' ')
    for a in p['visuals']:
        doc.append('| '+' | '.join(esc(s) for s in [a['id']+' '+a['title']+'; '+a['type'],a['source']+'; '+a['axis']+'; '+', '.join('['+m+']' for m in a['values']),a['filters']+'; '+a['sort'],a['tooltip']+'; '+a['interaction'],a['format']+'; '+str(a['rect'])])+' |')
    doc+=['']
    svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="800" viewBox="0 0 1280 800" role="img">',f'<title>Page {p["number"]}: {html.escape(p["title"])} — build wireframe</title>','<rect width="1280" height="800" fill="#F3F6F8"/>','<rect width="1280" height="6" fill="#12647A"/>']
    def text(x,y,t,size=14,fill='#172B3A',weight='normal'):
        svg.append(f'<text x="{x}" y="{y}" font-family="Segoe UI,Arial,sans-serif" font-size="{size}" font-weight="{weight}" fill="{fill}">{html.escape(t)}</text>')
    text(28,40,p['title'],26,weight='bold');text(28,66,p['question'],16)
    text(28,92,p['qualifier'],13)
    text(1000,40,'BUILD WIREFRAME',13,fill='#586975',weight='bold')
    for a in p['visuals']:
        x,y,w,h=a['rect'];svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="6" fill="white" stroke="#D0DCE3"/>')
        maxchars=max(22,int((w-28)/7.5));lines=textwrap.wrap(a['id']+'  '+a['title'],maxchars)
        yy=y+22
        for line in lines[:2]:text(x+14,yy,line,14,weight='bold');yy+=19
        if h>70:
            text(x+14,yy+3,textwrap.shorten(a['type']+' · '+a['source'],width=int((w-28)/6.5),placeholder='…'),12,fill='#586975');yy+=24
        content=a['format'] if a['type']=='Text' else (' · '.join(a['values']) or a['axis'])
        for line in textwrap.wrap(content,max(25,int((w-28)/7)))[:max(0,int((y+h-10-yy)/17)+1)]:text(x+14,yy,line,12,fill='#12647A');yy+=17
    text(28,785,'Layout specification only · source-backed build inputs · Desktop render/interaction acceptance still required',12,fill='#586975')
    svg.append('</svg>');(wire/f'page_{p["number"]}.svg').write_text('\n'.join(svg),encoding='utf-8')
doc+=['## Shared placement','', 'Top band (0–110): title, scope/release qualification and navigation. Put date/Zone controls in the filter pane, keeping the canvas uncluttered. Page 4 has an explicit event selection band. All other coordinates are in the register. Card groups are containers: divide evenly into labelled native Card visuals, preserving reading order. Composite entries (P5.6 and P5.7) use the chart on-canvas and a focus/detail table accessible through the existing page, not an unapproved sixth analytical page.','', 'For focus tables, include every listed column, enable word wrap and export, and keep full uncertainty/qualification text available. Do not crop qualifiers to make the layout fit.']
(ROOT/'docs/powerbi_pages.md').write_text('\n'.join(doc)+'\n',encoding='utf-8')
nav=''.join(f'<a href="#p{p["number"]}">{p["number"]}. {html.escape(p["title"])}</a> ' for p in pages)
body=''.join(f'<section id="p{p["number"]}"><h2>{html.escape(p["title"])}</h2><img src="wireframes/page_{p["number"]}.svg" alt="Page {p["number"]} layout wireframe"/></section>' for p in pages)
(HERE/'preview.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Power BI build package wireframes</title><style>body{font:16px Segoe UI,Arial;background:#F3F6F8;color:#172B3A;margin:24px}nav{position:sticky;top:0;background:white;padding:12px;display:flex;gap:18px;flex-wrap:wrap}a{color:#12647A}section{max-width:1280px;margin:36px auto}img{width:100%;height:auto}h1{font-size:24px}</style><h1>Phase 6 build package — layout review</h1><p>Wireframes only. No working PBIX/PBIP or rendered Power BI dashboard is claimed.</p><nav>'+nav+'</nav>'+body+'</html>',encoding='utf-8')
print(f'Generated {len(pages)} page specifications and {sum(len(p["visuals"]) for p in pages)} visual entries.')
